int decLen = 0;
TreeNode* current = root;
for (int i = 0; i < encLen; ++i) {
    if (!current) break;
    if (encoded[i] == 0) {
        current = current->left;
    } else {
        current = current->right;
    }
    if (current && !current->left && !current->right) {
        decoded[decLen++] = current->val;
        current = root;
    }
}
if (current && !current->left && !current->right && decLen == 0) {
    // Single-symbol tree case: fill with that symbol for each encoded bit (or once if no bits)
    decoded[decLen++] = current->val;
}

